PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS users (id INTEGER PRIMARY KEY AUTOINCREMENT, line_user_id TEXT UNIQUE NOT NULL, tags TEXT DEFAULT '[]', consent_at TEXT, blocked_at TEXT, created_at TEXT DEFAULT CURRENT_TIMESTAMP, last_used_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS stretch_types (id INTEGER PRIMARY KEY AUTOINCREMENT, slug TEXT UNIQUE NOT NULL, name TEXT NOT NULL, body_part TEXT NOT NULL, description TEXT NOT NULL, active INTEGER DEFAULT 1);
CREATE TABLE IF NOT EXISTS stretches (id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL, body_part TEXT NOT NULL, tags TEXT DEFAULT '[]', video_url TEXT, thumbnail_url TEXT, duration_seconds INTEGER DEFAULT 30, difficulty TEXT DEFAULT 'やさしい', caution TEXT DEFAULT '痛みのない範囲で行ってください。', published INTEGER DEFAULT 1, priority INTEGER DEFAULT 100);
CREATE TABLE IF NOT EXISTS stretch_type_stretches (stretch_type_id INTEGER REFERENCES stretch_types(id) ON DELETE CASCADE, stretch_id INTEGER REFERENCES stretches(id) ON DELETE CASCADE, position INTEGER, PRIMARY KEY(stretch_type_id,stretch_id));
CREATE TABLE IF NOT EXISTS assessments (id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER REFERENCES users(id), status TEXT DEFAULT 'in_progress', main_body_part TEXT, stretch_type_id INTEGER REFERENCES stretch_types(id), is_unsafe INTEGER DEFAULT 0, excluded_reason TEXT, ruleset_version INTEGER DEFAULT 1, question_version INTEGER DEFAULT 1, started_at TEXT DEFAULT CURRENT_TIMESTAMP, completed_at TEXT, seven_day_result TEXT);
CREATE TABLE IF NOT EXISTS assessment_answers (assessment_id INTEGER REFERENCES assessments(id) ON DELETE CASCADE, question_id TEXT, answer TEXT, PRIMARY KEY(assessment_id,question_id));
CREATE TABLE IF NOT EXISTS activity_logs (id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER REFERENCES users(id), assessment_id INTEGER REFERENCES assessments(id), stretch_id INTEGER REFERENCES stretches(id), event_type TEXT NOT NULL, event_key TEXT UNIQUE, created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS followup_outbox (id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER, assessment_id INTEGER, kind TEXT, due_at TEXT, scheduled_at TEXT, sent_at TEXT, canceled_at TEXT, attempts INTEGER DEFAULT 0, last_error TEXT, idempotency_key TEXT UNIQUE, status TEXT DEFAULT 'pending', UNIQUE(assessment_id,kind));
CREATE INDEX IF NOT EXISTS idx_followups_due ON followup_outbox(status,due_at);
CREATE INDEX IF NOT EXISTS idx_assessments_user ON assessments(user_id,status);
